SubProceso Dividir(a Como Entero, b Como Entero, cociente Como Entero Por Referencia, resto Como Entero Por Referencia)
  cociente <- a div b;
  resto <- a mod b;
FinSubProceso

Algoritmo Principal
  Definir c, r Como Entero;
  Dividir(17, 5, c, r);
  Escribir c, " ", r;
FinAlgoritmo

SubProceso Incrementar(n Como Entero Por Referencia)
  n <- n + 1;
FinSubProceso

Algoritmo Principal
  Incrementar(5);
FinAlgoritmo
